pub const Record = struct {
    block: b.Block,
    parent: ?*Record,
    utxo: t.Utxo,
    transaction_fees: []const i64,
    source: []const u8,
    fees: i64 = 0,
    work: i64 = 1,
    pub fn create(block: b.Block, parent: ?*Record, utxo: t.Utxo, fees: []const i64, source: []const u8) *Record {
        var record: Record = .{ .block = block, .parent = parent, .utxo = utxo, .transaction_fees = fees, .source = source };
        for (fees) |fee| record.fees += fee;
        if (parent) |previous| {
            var work: i64 = 1;
            for (0..h.u(block.difficulty)) |_| work *= 16;
            record.work = previous.work + work;
        }
        return h.create(Record, record);
    }
};
pub fn ancestor(record: *Record, height: i64) *Record {
    var current = record;
    while (current.block.height > height) current = current.parent.?;
    return current;
}
pub fn chainTo(record: *Record) []*Record {
    const result = h.alloc(*Record, h.u(record.block.height + 1));
    var current: ?*Record = record;
    var index = result.len;
    while (current) |value| {
        index -= 1;
        result[index] = value;
        current = value.parent;
    }
    return result;
}
pub fn forkPoint(first: *Record, second: *Record) *Record {
    const height = @min(first.block.height, second.block.height);
    var a = ancestor(first, height);
    var z = ancestor(second, height);
    while (a != z) {
        a = a.parent.?;
        z = z.parent.?;
    }
    return a;
}
pub const Block = struct {
    height: i64,
    previous: []const u8,
    root: []const u8,
    time: i64,
    difficulty: i64,
    nonce: i64 = 0,
    transactions: []const *const t.Transaction,
    hash: []const u8 = "",
    pub fn header(self: Block) []const u8 {
        return h.fmt("{d}|{s}|{s}|{d}|{d}|{d}", .{ self.height, self.previous, self.root, self.time,
             self.difficulty, self.nonce });
    }
    pub fn hashHeader(self: *Block) void {
        self.hash = h.digest(self.header());
    }
    pub fn size(self: Block) i64 {
        var value: i64 = 0;
        for (self.transactions[1..]) |tx| value += tx.size();
        return value;
    }
    pub fn proof(self: Block) bool {
        for (self.hash[0..h.u(self.difficulty)]) |character| if (character != '0') return false;
        return true;
    }
    pub fn ids(self: Block) []const []const u8 {
        const result = h.alloc([]const u8, self.transactions.len);
        for (self.transactions, result) |tx, *id| id.* = tx.id;
        return result;
    }
};
pub fn parse(fields: []const []const u8, texts: []const []const u8) Block {
    const txs = h.alloc(*const t.Transaction, texts.len);
    for (texts, txs) |text, *tx| tx.* = t.parse(text);
    var block: Block = .{ .height = h.number(fields[3]), .previous = fields[4], .root = fields[5],
         .time = h.number(fields[6]), .difficulty = h.number(fields[7]), .nonce = h.number(fields[8]),
         .transactions = txs };
    block.hashHeader();
    return block;
}
pub fn contextError(block: Block, limit: i64) ?[]const u8 {
    if (!block.proof()) return "bad-pow";
    if (!h.eq(h.merkle(block.ids()), block.root)) return "bad-merkle";
    if (block.transactions[0].coinbase_height == null or block.transactions[0].coinbase_height.? != block.height) return "bad-structure";
    for (block.transactions[1..]) |tx| if (tx.coinbase_height != null) return "bad-structure";
    if (block.size() > limit) return "too-large";
    return null;
}
pub const Reference = struct { id: []const u8, index: usize };
pub fn same(a: Reference, b: Reference) bool {
    return a.index == b.index and h.eq(a.id, b.id);
}
pub fn referenceOrder(a: Reference, b: Reference) bool {
    const order = std.mem.order(u8, a.id, b.id);
    return if (order == .eq) a.index < b.index else order == .lt;
}
pub const Transaction = struct {
    text: []const u8,
    id: []const u8,
    body: []const u8 = "",
    inputs: []const Reference = &.{},
    outputs: []const Output,
    signatures: []const []const u8 = &.{},
    coinbase_height: ?i64 = null,
    pub fn total(self: *const Transaction) i64 {
        var result: i64 = 0;
        for (self.outputs) |output| result += output.amount;
        return result;
    }
    pub fn size(self: *const Transaction) i64 {
        return h.n(self.text.len);
    }
};
pub const Coin = struct {
    reference: Reference,
    address: []const u8,
    amount: i64,
    height: i64,
    coinbase: bool,
    pub fn mature(self: Coin, height: i64, maturity: i64) bool {
        return !self.coinbase or self.height == 0 or height >= self.height + maturity;
    }
};
pub const Utxo = struct {
    coins: std.ArrayList(Coin) = .empty,
    pub fn find(self: *const Utxo, reference: Reference) ?Coin {
        for (self.coins.items) |coin| if (same(coin.reference, reference)) return coin;
        return null;
    }
    pub fn copy(self: Utxo) Utxo {
        var result: Utxo = .{};
        for (self.coins.items) |coin| h.append(Coin, &result.coins, coin);
        return result;
    }
    pub fn apply(self: *Utxo, tx: *const Transaction, height: i64) void {
        for (tx.inputs) |reference| {
            for (self.coins.items, 0..) |coin, index| if (same(coin.reference, reference)) {
                _ = self.coins.orderedRemove(index);
                break;
            };
        }
        for (tx.outputs, 0..) |output, index| {
            const coin: Coin = .{ .reference = .{ .id = tx.id, .index = index }, .address = output.address,
                 .amount = output.amount, .height = height, .coinbase = tx.coinbase_height != null };
            var replaced = false;
            for (self.coins.items) |*old| if (same(old.reference, coin.reference)) {
                old.* = coin;
                replaced = true;
                break;
            };
            if (!replaced) h.append(Coin, &self.coins, coin);
        }
    }
};
pub fn check(tx: *const Transaction, utxo: *const Utxo, spent: []const Reference, height: i64, wallets: []const w.Wallet,
     maturity: i64) Check {
    for (tx.outputs) |output| if (w.owner(wallets, output.address) == null or output.amount == 0) return .{ .reason = "bad-output" };
    var total: i64 = 0;
    for (tx.inputs, 0..) |reference, index| {
        for (spent) |other| if (same(reference, other)) return .{ .reason = "double-spend" };
        for (tx.inputs[0..index]) |other| if (same(reference, other)) return .{ .reason = "double-spend" };
        const coin = utxo.find(reference) orelse return .{ .reason = "missing-input" };
        if (!coin.mature(height, maturity)) return .{ .reason = "immature" };
        if (!h.eq(tx.signatures[index], w.sign(w.owner(wallets, coin.address).?.secret, index, tx.body))) return .{ .reason = "bad-sig" };
        total += coin.amount;
    }
    if (total < tx.total()) return .{ .reason = "overspend" };
    return .{ .fee = total - tx.total() };
}
pub fn dupe(comptime T: type, values: []const T) []T {
    return allocator.dupe(T, values) catch @panic("allocation failed");
}
